package com.ruoyi.metal.service;

import java.util.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
import com.alibaba.fastjson2.JSON;import com.alibaba.fastjson2.JSONObject;
import com.ruoyi.common.exception.ServiceException;import com.ruoyi.common.utils.SecurityUtils;
import com.ruoyi.metal.security.FactoryScope;import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.support.*;import org.springframework.transaction.annotation.*;
/** Authoritative saved-route policy, shared by candidates, import and posting. */
@Service
@Transactional(rollbackFor=Exception.class)
public class SemiSourcePolicyService {
 private final JdbcTemplate jdbc;private final FactoryScope scope;
 public SemiSourcePolicyService(JdbcTemplate j,FactoryScope s){jdbc=j;scope=s;}
 static long n(Object v){return SemiFlowService.num(v);}static String t(Object v){return SemiFlowService.text(v);}
 static String hash(Object v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(JSON.toJSONString(v).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private Map<String,Object> one(String q,Object...a){var r=jdbc.queryForList(q,a);if(r.size()!=1)throw new ServiceException("工艺许可或工单明细不存在");return r.get(0);}
 public List<Long> route(long item){return jdbc.queryForList("SELECT process_id FROM metal_work_order_step WHERE item_id=? ORDER BY sequence_no",item).stream().map(r->n(r.get("process_id"))).toList();}
 public Map<String,Object> context(long item){var c=one("SELECT i.*,w.factory_id,w.del_flag FROM metal_work_order_item i JOIN metal_work_order w ON w.work_order_id=i.work_order_id WHERE i.item_id=? AND w.del_flag='0'",item);scope.check(n(c.get("factory_id")));var p=JSON.parseObject(t(c.get("product_snapshot")));if(p==null||p.getString("specification")==null||p.getString("specification").isBlank())throw new ServiceException("缺少规格快照，请人工核对");c.put("spec",p.getString("specification").trim());c.put("route",route(item));return c;}
 public List<Map<String,Object>> permits(long item){var c=context(item);return jdbc.queryForList("SELECT p.*,v.snapshot FROM metal_route_skip_permit p JOIN metal_route_skip_permit_version v ON v.permit_id=p.permit_id AND v.version=p.version WHERE p.factory_id=? AND p.product_id=? AND BINARY p.specification=BINARY ? AND p.route_hash=? ORDER BY p.permit_id",c.get("factory_id"),c.get("product_id"),c.get("spec"),hash(c.get("route")));}
 public long configure(Long id,long item,int source,int target,Boolean enabled,Integer version,String uuid,String reason){
  if(!scope.isAdmin()&&!SecurityUtils.getLoginUser().getPermissions().contains("metal:route-skip:configure"))throw new ServiceException("无工艺跳步许可配置权限",403);
  if(uuid==null||!uuid.matches("[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}")||reason==null||reason.isBlank()||reason.length()>500||enabled==null)throw new ServiceException("请填写合法请求标识、状态及1至500字原因");
  var c=context(item);scope.lockFactories(List.of(n(c.get("factory_id"))));List<?> route=(List<?>)c.get("route");if(source<1||target>route.size()||target<=source+1)throw new ServiceException("请选择存在且需要跳步的来源和目标工序");
  String fp=hash(Arrays.asList(id,item,source,target,enabled,version,uuid,reason));long actor=SecurityUtils.getUserId();
  var replay=jdbc.queryForList("SELECT permit_id,request_hash,actor_id FROM metal_route_skip_permit_version WHERE request_id=?",uuid);if(!replay.isEmpty()){var r=replay.get(0);if(!fp.equals(r.get("request_hash"))||n(r.get("actor_id"))!=actor)throw new ServiceException("重复请求内容或人员不一致");return n(r.get("permit_id"));}
  if(id==null){var old=jdbc.queryForList("SELECT * FROM metal_route_skip_permit WHERE request_id=?",uuid);if(!old.isEmpty()){if(!fp.equals(old.get(0).get("request_hash"))||n(old.get(0).get("actor_id"))!=actor)throw new ServiceException("重复请求内容或人员不一致");return n(old.get(0).get("permit_id"));}
   KeyHolder h=new GeneratedKeyHolder();jdbc.update(conn->{var p=conn.prepareStatement("INSERT INTO metal_route_skip_permit(factory_id,product_id,specification,route_hash,route_snapshot,source_sequence,target_sequence,enabled,request_id,request_hash,actor_id,reason) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",java.sql.Statement.RETURN_GENERATED_KEYS);Object[] a={c.get("factory_id"),c.get("product_id"),c.get("spec"),hash(route),JSON.toJSONString(route),source,target,enabled,uuid,fp,actor,reason};for(int k=0;k<a.length;k++)p.setObject(k+1,a[k]);return p;},h);id=h.getKey().longValue();
  }else{var old=one("SELECT * FROM metal_route_skip_permit WHERE permit_id=? FOR UPDATE",id);scope.check(n(old.get("factory_id")));if(!Objects.equals(old.get("request_id"),uuid)&& (version==null||n(old.get("version"))!=version))throw new ServiceException("许可版本冲突，请刷新");if(n(old.get("factory_id"))!=n(c.get("factory_id"))||n(old.get("product_id"))!=n(c.get("product_id"))||!hash(route).equals(old.get("route_hash"))||!c.get("spec").equals(old.get("specification")))throw new ServiceException("不能改变许可的产品和路线身份");if(uuid.equals(old.get("request_id"))){if(!fp.equals(old.get("request_hash"))||n(old.get("actor_id"))!=actor)throw new ServiceException("重复请求内容不一致");return id;}jdbc.update("UPDATE metal_route_skip_permit SET source_sequence=?,target_sequence=?,enabled=?,version=version+1,request_id=?,request_hash=?,actor_id=?,reason=? WHERE permit_id=?",source,target,enabled,uuid,fp,actor,reason,id);}
  var saved=one("SELECT * FROM metal_route_skip_permit WHERE permit_id=?",id);jdbc.update("INSERT INTO metal_route_skip_permit_version(permit_id,version,snapshot,actor_id,request_id,request_hash) VALUES(?,?,?,?,?,?)",id,saved.get("version"),JSON.toJSONString(saved),actor,uuid,fp);return id;
 }
 static boolean hasSkipped(Map<String,Object> batch){if(batch.get("execution_snapshot")==null)return false;var j=JSON.parseObject(t(batch.get("execution_snapshot")));return j!=null&&j.getJSONArray("skipped")!=null&&!j.getJSONArray("skipped").isEmpty();}
 public Map<String,Object> decide(Map<String,Object> source,Map<String,Object> target,Long permitId,Integer permitVersion){
  long from=n(source.get("sequence_no")),to=n(target.get("sequence_no"));var added=RouteExecutionRules.skipped(from,to);
  if(!added.isEmpty()){
   if(n(source.get("work_order_id"))!=n(target.get("work_order_id"))||n(source.get("item_id"))!=n(target.get("item_id")))throw new ServiceException("跳步仅支持本工单同产品明细");
   if(permitId==null||permitVersion==null)throw new ServiceException("更早工序领用须选择明确的工艺跳步许可");
   var c=context(n(target.get("item_id")));var p=one("SELECT * FROM metal_route_skip_permit WHERE permit_id=?",permitId);
   if(!Boolean.TRUE.equals(p.get("enabled"))&&!"1".equals(t(p.get("enabled"))))throw new ServiceException("跳步许可已停用");
   if(n(p.get("factory_id"))!=n(c.get("factory_id"))||n(p.get("product_id"))!=n(c.get("product_id"))||!c.get("spec").equals(p.get("specification"))||!hash(c.get("route")).equals(p.get("route_hash"))||n(p.get("source_sequence"))!=from||n(p.get("target_sequence"))!=to||n(p.get("version"))!=permitVersion)throw new ServiceException("跳步许可、版本或保存路线与当前来源不匹配");
  }else if(permitId!=null)throw new ServiceException("紧邻上道工序不应关联跳步许可");
  var processed=new ArrayList<Long>();var skipped=new ArrayList<Long>();
  if(source.get("execution_snapshot")==null){for(long n=1;n<=from;n++)processed.add(n);}else{var x=JSON.parseObject(t(source.get("execution_snapshot")));processed.addAll(x.getList("processed",Long.class));skipped.addAll(x.getList("skipped",Long.class));}
  var trace=RouteExecutionRules.advance(processed,skipped,from,to);var result=new LinkedHashMap<String,Object>();result.put("processed",trace.processed());result.put("skipped",trace.skipped());result.put("newSkipped",trace.newSkipped());return result;
 }
 static boolean completeSavedRoute(JdbcTemplate jdbc,Map<String,Object> batch){long last=n(batch.get("sequence_no"));var steps=jdbc.queryForList("SELECT sequence_no,process_id FROM metal_work_order_step WHERE item_id=? AND sequence_no<=? ORDER BY sequence_no",batch.get("item_id"),last);if(last<1||steps.size()!=last)return false;for(int i=0;i<steps.size();i++)if(n(steps.get(i).get("sequence_no"))!=i+1)return false;if(batch.get("execution_snapshot")!=null){var trace=JSON.parseObject(t(batch.get("execution_snapshot")));var processed=trace.getList("processed",Long.class);var skipped=trace.getList("skipped",Long.class);if(processed==null||skipped==null||!skipped.isEmpty()||processed.size()!=last)return false;for(int i=0;i<processed.size();i++)if(processed.get(i)!=i+1)return false;}return true;}
 private static String profile(Map<String,Object> trace){return JSON.toJSONString(new TreeMap<>(Map.of("processed",trace.get("processed"),"skipped",trace.get("skipped"))));}
 public String existingProfile(long batch,Map<String,Object> target,long excludeLine){
  var current=one("SELECT execution_snapshot FROM metal_process_batch WHERE batch_id=?",batch);if(current.get("execution_snapshot")!=null)return profile(JSON.parseObject(t(current.get("execution_snapshot"))));
  String result=null;for(var source:jdbc.queryForList("SELECT b.*,u.execution_snapshot issue_execution_snapshot FROM metal_warehouse_order_line l JOIN metal_warehouse_order o ON o.order_id=l.order_id LEFT JOIN metal_inventory i ON i.inventory_id=l.inventory_id LEFT JOIN metal_process_batch b ON b.batch_id=i.origin_batch_id LEFT JOIN metal_route_skip_use u ON u.line_id=l.line_id WHERE o.batch_id=? AND o.type='PRODUCTION_OUT' AND o.status='POSTED' AND l.category='SEMI' AND l.line_id<>? ORDER BY l.line_id",batch,excludeLine)){
   if(source.get("batch_id")==null)throw new ServiceException("历史开放批次缺少半成品来源，请先人工核对或冲销");String prior;
   if(source.get("issue_execution_snapshot")!=null)prior=profile(JSON.parseObject(t(source.get("issue_execution_snapshot"))));
   else{if(n(source.get("sequence_no"))+1!=n(target.get("sequence_no")))throw new ServiceException("历史开放批次工艺轨迹不完整，请先核对");prior=profile(decide(source,target,null,null));}
   RouteExecutionRules.sameProfile(result,prior);result=prior;
  }return result;
 }
 public void bind(Map<String,Object> stock,Map<String,Object> target,Long permit,Integer version,long line){var source=one("SELECT * FROM metal_process_batch WHERE batch_id=?",stock.get("origin_batch_id"));var trace=decide(source,target,permit,version);String profile=JSON.toJSONString(new TreeMap<>(Map.of("processed",trace.get("processed"),"skipped",trace.get("skipped"))));one("SELECT execution_snapshot FROM metal_process_batch WHERE batch_id=? FOR UPDATE",target.get("batch_id"));String prior=existingProfile(n(target.get("batch_id")),target,line);RouteExecutionRules.sameProfile(prior,profile);jdbc.update("UPDATE metal_process_batch SET execution_snapshot=? WHERE batch_id=?",profile,target.get("batch_id"));if(permit!=null)jdbc.update("INSERT INTO metal_route_skip_use(line_id,permit_id,permit_version,item_id,batch_id,new_skipped,execution_snapshot) VALUES(?,?,?,?,?,?,?)",line,permit,version,target.get("item_id"),target.get("batch_id"),JSON.toJSONString(trace.get("newSkipped")),profile);}
 public long skipCredit(long item,long sequence){long total=0;for(var r:jdbc.queryForList("SELECT u.new_skipped,l.quantity-COALESCE(r.quantity,0) quantity FROM metal_route_skip_use u JOIN metal_warehouse_order_line l ON l.line_id=u.line_id JOIN metal_warehouse_order o ON o.order_id=l.order_id JOIN metal_process_batch b ON b.batch_id=u.batch_id LEFT JOIN (SELECT x.source_line_id,SUM(x.quantity) quantity FROM metal_warehouse_order_line x JOIN metal_warehouse_order d ON d.order_id=x.order_id WHERE d.status='POSTED' AND d.type='SEMI_RETURN' GROUP BY x.source_line_id) r ON r.source_line_id=l.line_id WHERE u.item_id=? AND o.status='POSTED' AND b.status<>'VOID'",item)){if(JSON.parseArray(t(r.get("new_skipped")),Long.class).contains(sequence))total+=n(r.get("quantity"));}return total;}
}
